mapper.select:
select count(case when check_in_at is not null then 1 end) as work_days,
       count(case when status = 'LATE' then 1 end) as late_count,
       count(case when status = 'EARLY_LEAVE' then 1 end) as early_leave_count
from attendance
where emp_id = #{empId}
  and work_date between #{from} and #{to}

select coalesce(sum(floor(timestampdiff(minute, timestamp(work_date, '18:00:00'), check_out_at) / 30) * 0.5), 0)
from attendance
where emp_id = #{empId}
  and work_date between #{from} and #{to}
  and check_out_at > timestamp(work_date, '18:00:00')

select attendance_id, emp_id, work_date, check_in_at, check_out_at, status
from attendance
where emp_id = #{empId}
  and work_date <= #{today}
order by work_date desc
limit 5
